package net.civeira.phylax.feature.identity.tenantloginprovider.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.tenantloginprovider.domain.TenantLoginProvider;
import net.civeira.phylax.feature.identity.tenantloginprovider.domain.valueobject.OidcClaimMappingVO;

class OidcClaimMappingValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of oidc claim mapping of tenant login provider")
  void test_oidc_claim_mapping_value_holder_assign_plain_value() {
    Object holder = new Object();
    OidcClaimMappingValueHolder<Object> value = new OidcClaimMappingValueHolder<>(holder);
    Assertions.assertSame(holder, value.oidcClaimMapping("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getOidcClaimMappingValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getOidcClaimMapping().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.oidcClaimMappingNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getOidcClaimMappingValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getOidcClaimMapping().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of oidc claim mapping of tenant login provider")
  void test_oidc_claim_mapping_value_holder_assign_value_object() {
    Object holder = new Object();
    OidcClaimMappingValueHolder<Object> value = new OidcClaimMappingValueHolder<>(holder);
    OidcClaimMappingVO vo = OidcClaimMappingVO.from("one");
    Assertions.assertFalse(value.getOidcClaimMappingValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.oidcClaimMapping(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getOidcClaimMappingValue().orElseThrow());
    Assertions.assertSame(holder, value.oidcClaimMapping(Optional.empty()));
    Assertions.assertFalse(value.getOidcClaimMappingValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.oidcClaimMapping(Optional.of(vo)));
    Assertions.assertSame(vo, value.getOidcClaimMappingValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of oidc claim mapping of tenant login provider against the original")
  void test_oidc_claim_mapping_value_holder_read() {
    Object holder = new Object();
    OidcClaimMappingValueHolder<Object> value = new OidcClaimMappingValueHolder<>(holder);
    OidcClaimMappingVO vo = OidcClaimMappingVO.from("one");
    OidcClaimMappingVO other = OidcClaimMappingVO.from("one");
    TenantLoginProvider original = Mockito.mock(TenantLoginProvider.class);
    Mockito.when(original.getOidcClaimMappingValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readOidcClaimMapping(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readOidcClaimMapping(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.oidcClaimMapping(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readOidcClaimMapping(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readOidcClaimMapping(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of oidc claim mapping of tenant login provider")
  void test_oidc_claim_mapping_value_holder_unset() {
    Object holder = new Object();
    OidcClaimMappingValueHolder<Object> value = new OidcClaimMappingValueHolder<>(holder);
    OidcClaimMappingVO vo = OidcClaimMappingVO.from("one");
    value.oidcClaimMapping(vo);
    Assertions.assertSame(holder, value.unsetOidcClaimMappingIfMatches("oidcClaimMapping_other"));
    Assertions.assertTrue(value.getOidcClaimMappingValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetOidcClaimMappingIfMatches("oidcClaimMapping"));
    Assertions.assertFalse(value.getOidcClaimMappingValue().isPresent(),
        "The field name must clear the value");
    value.oidcClaimMapping(vo);
    Assertions.assertSame(holder, value.unsetOidcClaimMapping());
    Assertions.assertFalse(value.getOidcClaimMappingValue().isPresent(),
        "Unset must clear the value");
  }
}
